<script setup lang="ts">import { ref } from 'vue';import { saveAs } from 'file-saver';import { request, requestBlob } from '@/lib/request';const props = defineProps<{ resource: string }>(), pending = ref(false), error = ref(''), emit = defineEmits<{ uploaded: [id:string] }>();async function upload(event:Event) { const file = (event.target as HTMLInputElement).files?.[0];if (!file) return;pending.value = true;error.value = '';try { const form = new FormData();form.set('file', file);const result = await request<{ fileId: string }>('/api/platform/files', { method: 'POST', query: { resource: props.resource }, body: form });emit('uploaded', result.fileId) } catch(e) { error.value = e instanceof Error ? e.message : '上传失败' } finally { pending.value = false } } async function download(id:string) { const metadata = await request<{ orignalName: string }>('/api/platform/files/' + encodeURIComponent(id), { query: { resource: props.resource }});const blob = await requestBlob('/api/platform/files/' + encodeURIComponent(id) + '/content', { query: { resource: props.resource }});saveAs(blob, metadata.orignalName) }defineExpose({ download })</script><template><label><input type="file" :disabled="pending" @change="upload"><span v-if="pending">上传中…</span><span v-if="error" role="alert">{{ error }}</span></label></template>
